void Sender::RobotStateInit(){
  Command command_temp(0x31010C05,0, 0);
  CmdDone(command_temp);
  usleep(1000*1000*7);
  Command command_temp_1(0x0114,0,0);
  CmdDone(command_temp_1);//PS：超过5ms，未发数据set_send(cmd)，会失去控制权，要重新发送获取控制权
  CmdDone(command_temp_1);//PS：超过5ms，未发数据set_send(cmd)，会失去控制权，要重新发送获取控制权
}
